package lombok;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import lombok.DirectoryRunner.FileTester;
import lombok.transform.TestWithEcj;

public class ManyEcj {
  public static void main(String[] args) throws Exception {
    String prefix = args.length > 0 ? args[0] : "";
    lombok.transform.TestWithEcj params = new lombok.transform.TestWithEcj();
    List<String> fails = new ArrayList<>();
    for (File f : params.getBeforeDirectory().listFiles()) {
      if (!f.getName().endsWith(".java") || !f.getName().startsWith(prefix)) continue;
      FileTester tester;
      try {
        tester = new lombok.RunTestsViaEcj().createTester(params, f, params.getCompiler() == null ? "ecj" : "ecj", params.getVersion(), false);
      } catch (Exception e) { System.out.println("SKIP " + f.getName() + " : " + e); continue; }
      if (tester == null) continue;
      try {
        tester.runTest();
        System.out.println("PASS " + f.getName());
      } catch (Throwable t) {
        fails.add(f.getName());
        System.out.println("FAIL " + f.getName() + " : " + t.getMessage());
      }
    }
    System.out.println("FAILURES: " + fails);
    if (!fails.isEmpty()) System.exit(1);
  }
}
EOF
